package com.jobmatcher.security;
import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.util.Base64;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;
@Component public class TokenService { @Value("${app.jwt.secret}") private String secret; private String sign(String s){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} public String create(Long id){long exp=System.currentTimeMillis()+86400000L;String body=id+":"+exp;return Base64.getUrlEncoder().withoutPadding().encodeToString(body.getBytes(StandardCharsets.UTF_8))+"."+sign(body);} public Long verify(String token){try{String[] p=token.split("\\.");String body=new String(Base64.getUrlDecoder().decode(p[0]),StandardCharsets.UTF_8);if(!java.security.MessageDigest.isEqual(sign(body).getBytes(),p[1].getBytes()))return null;String[] v=body.split(":");if(Long.parseLong(v[1])<System.currentTimeMillis())return null;return Long.parseLong(v[0]);}catch(Exception e){return null;}} }
